import sys


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    shows = [(int(data[1 + 2 * i]), int(data[2 + 2 * i])) for i in range(n)]
    best = 0
    for mask in range(1 << n):
        chosen = [shows[i] for i in range(n) if (mask >> i) & 1]
        if len(chosen) <= best:
            continue
        ok = True
        for i in range(len(chosen)):
            for j in range(i + 1, len(chosen)):
                a = chosen[i]
                b = chosen[j]
                if not (a[1] < b[0] or b[1] < a[0]):
                    ok = False
                    break
            if not ok:
                break
        if ok:
            best = len(chosen)
    print(best)


main()
